import math

def trop_add(a, b): return max(a, b)
def trop_mul(a, b): return a + b
def relu(x): return max(x, 0.0)

# Tropical distributivity
for a, b, c in [(2,3,5), (-1,4,2), (0,0,0)]:
    lhs = trop_mul(a, trop_add(b, c))
    rhs = trop_add(trop_mul(a, b), trop_mul(a, c))
    print(f"a={a}, b={b}, c={c}: LHS={lhs}, RHS={rhs}, equal={abs(lhs-rhs)<1e-12}")

# ReLU = tropical addition with 0
for x in [-3, -1, 0, 1, 5]:
    print(f"ReLU({x}) = {relu(x)} = max({x}, 0) = {trop_add(x, 0)}")

import math

def logsumexp(a, b):
    m = max(a, b)
    return m + math.log(math.exp(a - m) + math.exp(b - m))

log2 = math.log(2)
for a, b in [(1,2), (5,5), (-3,3), (10,-10)]:
    lse = logsumexp(a, b)
    mx = max(a, b)
    gap = lse - mx
    print(f"a={a}, b={b}: max={mx}, LSE={lse:.6f}, gap={gap:.6f} <= log2={log2:.6f}: {gap <= log2 + 1e-10}")

import math

def logsumexp_multi(z):
    m = max(z)
    return m + math.log(sum(math.exp(zi - m) for zi in z))

def eml_score(phi, eps):
    return eps * logsumexp_multi([v / eps for v in phi])

# 3-class classifier, d=4 pieces/class
phi = [[3,2.5,1,0.5], [8,7.5,6,5], [4,3.5,2,1.5]]
y_true, L, d = 1, 2.0, 4

trop_scores = [max(p) for p in phi]
gamma = trop_scores[y_true] - max(s for k,s in enumerate(trop_scores) if k != y_true)
print(f"Tropical margin: {gamma}")

for eps in [0.01, 0.1, 0.5, 1.0, 2.0]:
    gamma_eff = gamma - 2*eps*math.log(d)
    radius = max(0, gamma_eff / (2*L))
    print(f"eps={eps}: effective_margin={gamma_eff:.3f}, radius={radius:.4f}")
